-- Changelog-item: EVA-eigen bevestigingsvensters in plaats van de browserpopups.
insert into public.changelog (datum, categorie, module, titel, omschrijving) values
  ('2026-08-03','verbeterd','Algemeen','Bevestigingsvensters in de huisstijl van EVA',
   'Vragen als "Weet je het zeker?" verschenen tot nu toe in het kale venster van de browser. Overal in EVA krijg je nu een eigen venster in de vertrouwde stijl, met een duidelijke knop die vertelt wat er gebeurt — bijvoorbeeld "Verwijderen" in plaats van "OK". Bij het afwijzen van een opleverpunt of meerwerk typ je de reden voortaan in een net invoerveld.');
